def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # The two ordered color groups are encoded by the nonzero runs in the bottom row.
    runs=[]; cur=[]
    for x in grid[-1]:
        if x:
            cur.append(x)
        elif cur:
            runs.append(cur); cur=[]
    if cur: runs.append(cur)
    groups=[r for r in runs if len(r)>1]
    top=[]
    for x in grid[0]:
        if x: top.append(x)
        elif top: break
    if len(top)>1: groups.insert(0,top)
    for r in range(h-1):
        for c in range(w):
            v=grid[r][c]
            if not v: continue
            if any((0<=r+dr<h and 0<=c+dc<w and grid[r+dr][c+dc]) for dr,dc in ((-1,0),(1,0),(0,-1),(0,1))): continue
            group=next((g for g in groups if v in g),None)
            if group is None: continue
            start=c-group.index(v)
            for i,x in enumerate(group):
                cc=start+i
                if 0<=cc<w: out[r][cc]=x
    return out
